script-structure.example:
#!/usr/bin/env bash set -euo pipefail
readonly SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)" readonly SCRIPT_NAME="$(basename "${BASH_SOURCE[0]}")"
# ── Configuration (with defaults) ───────────────────── LOG_LEVEL="${LOG_LEVEL:-info}" OUTPUT_DIR="${OUTPUT_DIR:-./output}"
# ── Functions ────────────────────────────────────────── usage() { printf 'Usage: %s [OPTIONS]\n' "$SCRIPT_NAME" printf ' -h Show this help\n' exit 2 }
cleanup() { local exit_code=$? rm -f "${tmpfile:-}" exit "$exit_code" }
main() { while getopts ":h" opt; do case "$opt" in h) usage ;; *) usage ;; esac done shift $(( OPTIND - 1 ))
printf 'Starting %s\n' "$SCRIPT_NAME" }
# ── Traps & Entry ───────────────────────────────────── trap cleanup EXIT trap 'echo "Interrupted" >&2; exit 130' INT TERM main "$@"

testing.example:
# test/deploy.bats
setup()    { export TMPDIR="$(mktemp -d)"; }
teardown() { rm -rf "$TMPDIR"; }

@test "deploy requires environment argument" {
    run ./deploy.sh
    [ "$status" -ne 0 ]
    [[ "$output" == *"Usage:"* ]]
}

@test "deploy creates output directory" {
    run ./deploy.sh staging
    [ "$status" -eq 0 ]
    [ -d "$TMPDIR/output" ]
}
